# -*- coding: utf-8 -*-\n# =============================================================================\n# Process Name: PixelRAG Search Provider with FAISS Index\n# =============================================================================\n# Description:\n#   FAISS-based visual search provider for PixelRAG. Maintains semantic index\n#   of image embeddings and provides similarity search interface compatible\n#   with DocumentRAGManager.\n#\n# File: pixel_rag.py\n# Project: ai-breadboard\n# Package: src.rag.pixel\n# Author: hypo69\n# Copyright: © 2026 hypo69\n# =============================================================================\n\nfrom __future__ import annotations\n\nimport asyncio\nimport json\nimport logging\nimport time\nfrom dataclasses import asdict\nfrom pathlib import Path\nfrom typing import Any, Dict, List, Optional, Tuple\n\nimport numpy as np\n\ntry:\n    import faiss\n    FAISS_AVAILABLE = True\nexcept ImportError:\n    FAISS_AVAILABLE = False\n\nfrom src.rag.pixel.embedder import PixelEmbedder, ImageEmbedding\n\n\nlogger = logging.getLogger(__name__)\n\n\nclass PixelRAG:\n    \"\"\"\n    ## hypo69 docblock\n    Visual search provider using FAISS index for semantic image retrieval.\n    \n    Compatible interface with DocumentRAGManager for unified RAG access:\n    - add_documents(docs): Index images\n    - search(query): Semantic search\n    - get_index_stats(): Get metadata\n    \n    Features:\n    - FAISS FlatL2 index for similarity search\n    - SHA-256 deduplication\n    - Version tracking\n    - Persistent index storage\n    \"\"\"\n\n    def __init__(\n        self,\n        index_dir: Path = Path(\"data/rag_index/pixel_rag\"),\n        embedder: Optional[PixelEmbedder] = None,\n        index_type: str = \"FlatL2\"\n    ) -> None:\n        \"\"\"\n        ## hypo69 docblock\n        Initialize PixelRAG provider.\n\n        Args:\n            index_dir: Directory for storing FAISS index and metadata\n            embedder: PixelEmbedder instance (creates new if None)\n            index_type: FAISS index type ('FlatL2' or 'IVF')\n        \"\"\"\n        if not FAISS_AVAILABLE:\n            raise ImportError(\n                \"faiss not available. Install: pip install faiss-cpu\"\n            )\n\n        self.index_dir = Path(index_dir)\n        self.index_dir.mkdir(parents=True, exist_ok=True)\n        self.embedder = embedder or PixelEmbedder()\n        self.index_type = index_type\n\n        # Index files\n        self.index_file = self.index_dir / \"index.faiss\"\n        self.metadata_file = self.index_dir / \"metadata.json\"\n        self.chunks_file = self.index_dir / \"chunks.jsonl\"\n        self.index_info_file = self.index_dir / \"info.json\"\n\n        # In-memory state\n        self._index: Optional[faiss.Index] = None\n        self._chunks: List[Dict[str, Any]] = []\n        self._metadata: Dict[str, Any] = {}\n\n        # Load existing index\n        self._load_index()\n\n    def _load_index(self) -> None:\n        \"\"\"\n        ## hypo69 docblock\n        Load FAISS index and metadata from disk.\n        \"\"\"\n        try:\n            if self.index_file.exists():\n                logger.info(f\"Loading FAISS index from {self.index_file}\")\n                self._index = faiss.read_index(str(self.index_file))\n                logger.info(\n                    f\"Index loaded: {self._index.ntotal} vectors, \"\n                    f\"dimension {self._index.d}\"\n                )\n\n            # Load metadata\n            if self.metadata_file.exists():\n                with open(self.metadata_file, 'r', encoding='utf-8') as f:\n                    self._metadata = json.load(f)\n\n            # Load chunks\n            if self.chunks_file.exists():\n                with open(self.chunks_file, 'r', encoding='utf-8') as f:\n                    self._chunks = [\n                        json.loads(line) for line in f\n                        if line.strip()\n                    ]\n                logger.info(f\"Loaded {len(self._chunks)} chunks\")\n\n            # Load info\n            if self.index_info_file.exists():\n                with open(self.index_info_file, 'r', encoding='utf-8') as f:\n                    info = json.load(f)\n                    logger.info(\n                        f\"Index info: {info.get('total_indexed', 0)} \"\n                        f\"documents indexed\"\n                    )\n\n        except Exception as e:\n            logger.warning(f\"Failed to load existing index: {e}\")\n            self._index = None\n            self._chunks = []\n            self._metadata = {}\n\n    def _save_index(self) -> None:\n        \"\"\"\n        ## hypo69 docblock\n        Save FAISS index and metadata to disk.\n        \"\"\"\n        try:\n            if self._index is not None:\n                faiss.write_index(self._index, str(self.index_file))\n                logger.info(f\"Saved FAISS index with {self._index.ntotal} vectors\")\n\n            # Save metadata\n            with open(self.metadata_file, 'w', encoding='utf-8') as f:\n                json.dump(self._metadata, f, ensure_ascii=False, indent=2)\n\n            # Save chunks\n            with open(self.chunks_file, 'w', encoding='utf-8') as f:\n                for chunk in self._chunks:\n                    f.write(json.dumps(chunk, ensure_ascii=False) + \"\\n\")\n\n            # Save info\n            info = {\n                \"index_type\": self.index_type,\n                \"total_indexed\": len(self._chunks),\n                \"dimension\": self._index.d if self._index else 512,\n                \"last_updated\": time.time(),\n                \"model\": self.embedder.MODEL_NAME\n            }\n            with open(self.index_info_file, 'w', encoding='utf-8') as f:\n                json.dump(info, f, ensure_ascii=False, indent=2)\n\n        except Exception as e:\n            logger.error(f\"Failed to save index: {e}\")\n\n    async def add_documents(\n        self,\n        documents: List[Dict[str, Any]]\n    ) -> int:\n        \"\"\"\n        ## hypo69 docblock\n        Index images from documents.\n\n        DocumentRAGManager compatible interface.\n\n        Args:\n            documents: List of documents with format:\n                {\n                    'id': 'unique_id',\n                    'text': 'image_path_or_url',\n                    'meta': {'image_path': '...', 'doc_type': 'image', ...}\n                }\n\n        Returns:\n            int: Number of documents indexed\n        \"\"\"\n        if not documents:\n            logger.warning(\"No documents to index\")\n            return 0\n\n        logger.info(f\"Indexing {len(documents)} documents\")\n\n        # Extract image paths\n        image_sources = []\n        for doc in documents:\n            # Try different field names\n            image_path = (\n                doc.get('meta', {}).get('image_path') or\n                doc.get('text') or\n                doc.get('path')\n            )\n            if image_path:\n                image_sources.append({\n                    'id': doc.get('id', f\"doc_{len(image_sources)}\"),\n                    'source': image_path,\n                    'meta': doc.get('meta', {})\n                })\n\n        if not image_sources:\n            logger.warning(\"No image sources found in documents\")\n            return 0\n\n        # Embed all images\n        embeddings = await self.embedder.embed_batch(\n            [s['source'] for s in image_sources],\n            use_cache=True\n        )\n\n        # Build or update index\n        if len(embeddings) == 0:\n            logger.warning(\"No embeddings generated\")\n            return 0\n\n        vectors = np.stack(\n            [e.vector for e in embeddings]\n        ).astype(np.float32)\n\n        # Create or append to index\n        if self._index is None:\n            # Create new index\n            dimension = vectors.shape[1]\n            if self.index_type == \"FlatL2\":\n                self._index = faiss.IndexFlatL2(dimension)\n            elif self.index_type == \"IVF\":\n                nlist = max(1, len(embeddings) // 10)\n                quantizer = faiss.IndexFlatL2(dimension)\n                self._index = faiss.IndexIVFFlat(quantizer, dimension, nlist)\n                self._index.train(vectors)\n\n        # Add vectors\n        self._index.add(vectors)\n\n        # Store metadata\n        for i, (emb, src) in enumerate(zip(embeddings, image_sources)):\n            chunk = {\n                \"chunk_id\": f\"{src['id']}#visual\",\n                \"source_id\": src['id'],\n                \"source_path\": str(src['source']),\n                \"source_type\": \"pixel\",\n                \"embedding_id\": emb.embedding_id,\n                \"index_position\": len(self._chunks),\n                \"vector_index\": self._index.ntotal - len(embeddings) + i,\n                \"timestamp\": time.time(),\n                \"meta\": src['meta']\n            }\n            self._chunks.append(chunk)\n            self._metadata[emb.embedding_id] = asdict(emb.metadata)\n\n        # Save to disk\n        self._save_index()\n\n        logger.info(f\"Indexed {len(embeddings)} documents\")\n        return len(embeddings)\n\n    async def search(\n        self,\n        query: str,\n        top_k: int = 5,\n        threshold: float = 0.0\n    ) -> List[Dict[str, Any]]:\n        \"\"\"\n        ## hypo69 docblock\n        Semantic search for images matching text query.\n\n        DocumentRAGManager compatible interface.\n\n        Args:\n            query: Text query (e.g., \"Where is the save button?\")\n            top_k: Number of results\n            threshold: Minimum similarity score (unused for L2 distance)\n\n        Returns:\n            List[Dict]: Search results with format:\n                {\n                    'id': 'chunk_id',\n                    'text': 'image_path',\n                    'score': 0.95,  # Cosine similarity 0-1\n                    'meta': {...}\n                }\n        \"\"\"\n        if self._index is None or self._index.ntotal == 0:\n            logger.warning(\"Index is empty\")\n            return []\n\n        # Embed query\n        logger.info(f\"Searching: {query}\")\n        query_vector = await self.embedder.embed_text(query)\n        query_vector = query_vector.astype(np.float32).reshape(1, -1)\n\n        # Search\n        distances, indices = self._index.search(query_vector, k=top_k)\n\n        # Convert L2 distances to similarity scores\n        results = []\n        for idx, distance in zip(indices[0], distances[0]):\n            if idx < 0 or idx >= len(self._chunks):\n                continue\n\n            chunk = self._chunks[idx]\n\n            # Convert L2 distance to cosine similarity\n            # L2 distance between normalized vectors ≈ sqrt(2 - 2*cosine_sim)\n            l2_dist = float(distance)\n            cosine_sim = max(0.0, 1.0 - (l2_dist ** 2) / 2)\n\n            result = {\n                \"id\": chunk.get(\"chunk_id\"),\n                \"text\": chunk.get(\"source_path\"),\n                \"score\": cosine_sim,\n                \"source_type\": chunk.get(\"source_type\"),\n                \"meta\": chunk.get(\"meta\", {})\n            }\n            results.append(result)\n\n        logger.info(f\"Found {len(results)} results\")\n        return results\n\n    async def search_image(\n        self,\n        image_source: str | Path,\n        top_k: int = 5\n    ) -> List[Dict[str, Any]]:\n        \"\"\"\n        ## hypo69 docblock\n        Search for similar images (image-to-image search).\n\n        Args:\n            image_source: Path to query image\n            top_k: Number of results\n\n        Returns:\n            List[Dict]: Similar images with scores\n        \"\"\"\n        if self._index is None or self._index.ntotal == 0:\n            logger.warning(\"Index is empty\")\n            return []\n\n        # Embed query image\n        logger.info(f\"Searching similar images to {image_source}\")\n        query_emb = await self.embedder.embed_image(image_source)\n        query_vector = query_emb.vector.astype(np.float32).reshape(1, -1)\n\n        # Search\n        distances, indices = self._index.search(query_vector, k=top_k)\n\n        # Convert results\n        results = []\n        for idx, distance in zip(indices[0], distances[0]):\n            if idx < 0 or idx >= len(self._chunks):\n                continue\n\n            chunk = self._chunks[idx]\n            l2_dist = float(distance)\n            cosine_sim = max(0.0, 1.0 - (l2_dist ** 2) / 2)\n\n            result = {\n                \"id\": chunk.get(\"chunk_id\"),\n                \"text\": chunk.get(\"source_path\"),\n                \"score\": cosine_sim,\n                \"source_type\": chunk.get(\"source_type\"),\n                \"meta\": chunk.get(\"meta\", {})\n            }\n            results.append(result)\n\n        return results\n\n    def get_index_stats(self) -> Dict[str, Any]:\n        \"\"\"\n        ## hypo69 docblock\n        Get index statistics.\n\n        Returns:\n            Dict: Index stats\n        \"\"\"\n        stats = {\n            \"total_vectors\": self._index.ntotal if self._index else 0,\n            \"total_chunks\": len(self._chunks),\n            \"index_type\": self.index_type,\n            \"dimension\": self._index.d if self._index else 512,\n            \"memory_mb\": (\n                self._index.ntotal * self._index.d * 4 / (1024 * 1024)\n                if self._index else 0\n            ),\n            \"index_path\": str(self.index_file),\n            \"model\": self.embedder.MODEL_NAME,\n            \"index_exists\": self.index_file.exists()\n        }\n        return stats\n\n    async def delete_documents(\n        self,\n        source_ids: List[str]\n    ) -> int:\n        \"\"\"\n        ## hypo69 docblock\n        Delete indexed documents by source ID.\n\n        Note: FAISS doesn't support deletion directly.\n        Mark as deleted instead.\n\n        Args:\n            source_ids: List of source IDs to delete\n\n        Returns:\n            int: Number of documents marked as deleted\n        \"\"\"\n        deleted_count = 0\n        for chunk in self._chunks:\n            if chunk.get('source_id') in source_ids:\n                chunk['deleted'] = True\n                deleted_count += 1\n\n        self._save_index()\n        logger.info(f\"Marked {deleted_count} documents as deleted\")\n        return deleted_count\n\n    async def rebuild_index(self) -> None:\n        \"\"\"\n        ## hypo69 docblock\n        Rebuild index from scratch (remove deleted documents).\n        \"\"\"\n        logger.info(\"Rebuilding index...\")\n\n        # Filter out deleted chunks\n        active_chunks = [\n            c for c in self._chunks\n            if not c.get('deleted', False)\n        ]\n\n        if not active_chunks:\n            logger.warning(\"No active chunks to index\")\n            self._index = None\n            self._chunks = []\n            self._save_index()\n            return\n\n        # Re-embed all active chunks\n        image_sources = [\n            c['source_path'] for c in active_chunks\n        ]\n        embeddings = await self.embedder.embed_batch(\n            image_sources,\n            use_cache=True\n        )\n\n        # Create new index\n        vectors = np.stack(\n            [e.vector for e in embeddings]\n        ).astype(np.float32)\n\n        dimension = vectors.shape[1]\n        if self.index_type == \"FlatL2\":\n            self._index = faiss.IndexFlatL2(dimension)\n        elif self.index_type == \"IVF\":\n            nlist = max(1, len(embeddings) // 10)\n            quantizer = faiss.IndexFlatL2(dimension)\n            self._index = faiss.IndexIVFFlat(quantizer, dimension, nlist)\n            self._index.train(vectors)\n\n        self._index.add(vectors)\n        self._chunks = active_chunks\n\n        # Update vector indices\n        for i, chunk in enumerate(self._chunks):\n            chunk['vector_index'] = i\n\n        self._save_index()\n        logger.info(f\"Rebuilt index with {len(active_chunks)} chunks\")\n\n    async def export_index(\n        self,\n        export_path: Path\n    ) -> None:\n        \"\"\"\n        ## hypo69 docblock\n        Export index for deployment.\n\n        Args:\n            export_path: Path to export directory\n        \"\"\"\n        export_path = Path(export_path)\n        export_path.mkdir(parents=True, exist_ok=True)\n\n        # Copy files\n        import shutil\n        for file in [self.index_file, self.metadata_file,\n                     self.chunks_file, self.index_info_file]:\n            if file.exists():\n                shutil.copy(file, export_path / file.name)\n\n        logger.info(f\"Index exported to {export_path}\")\n\n    async def cleanup(self) -> None:\n        \"\"\"\n        ## hypo69 docblock\n        Save index and cleanup resources.\n        \"\"\"\n        self._save_index()\n        await self.embedder.cleanup()\n        logger.info(\"PixelRAG cleaned up\")\n"